  // ---------- sentences with names: {x} name (kept), {w} label (translated), {n} number ----------
  const rule = (en, th) => {
    const keys = [];
    const src = en.replace(/[.*+?^$()|[\]\\]/g, '\\$&').replace(/\{([xwtn]\d?)\}/g, (m, k) => { keys.push(k); return k[0] === 'n' ? '(-?[\\d.,]+%?)' : '(.+?)'; });
    // {w} must be a known label (otherwise the rule is skipped); {t} is translated recursively
    T.rules.push([new RegExp('^' + src + '$'), (m, word, tr) => {
      let ok = true;
      const out = th.replace(/\{([xwtn]\d?)\}/g, (q, k) => {
        const v = m[keys.indexOf(k) + 1];
        if (k[0] === 'w') { const w = word(v); if (w === v) ok = false; return w; }
        if (k[0] === 't') return tr(v);
        return v === 'You' || v === 'you' ? 'คุณ' : v; // "You ran a campaign…" uses the same sentences as rivals
      });
      return ok ? out : null;
    }]);
  };
